"""Check If a String Contains All Binary Codes of Size K — count distinct windows.

There are 2^k codes; collect every length-k window and compare the set size.

Time: O(n * k)   Space: O(2^k)
"""


class Solution:
    def hasAllCodes(self, s: str, k: int) -> bool:
        if len(s) < k:
            return False
        return len({s[i:i + k] for i in range(len(s) - k + 1)}) == 1 << k
